from pathlib import Path
from zipfile import ZipFile,ZIP_DEFLATED
p=Path('practice-prompts/independent-check');out=p/'revised';out.mkdir(exist_ok=True)
with ZipFile(p/'input-original.zip') as z:
 for n in z.namelist():(out/n).write_bytes(z.read(n))
s=(out/'specification.txt').read_text().replace('Начинай отдельную дугу каждой точки; внешней рамки нет.','Собери все окружности вертикальных и горизонтальных линий в один путь: beginPath один раз, перед каждой arc вызови moveTo(x + radius, y), затем один fill после обоих циклов. Не вызывай fill для каждой точки или линии: на пересечениях иначе накапливается непрозрачность. Внешней рамки нет.')
s+='''

ОБЯЗАТЕЛЬНАЯ СТРУКТУРА ИНТЕРФЕЙСА
Эти требования уточняют общие формулировки выше. Не заменяй их собственной компоновкой.

1. Шапка панели: слева «Свойства», справа только кнопка сброса. Загрузка находится справа в строке заголовка «Изображение», а не в шапке панели. До загрузки допустима дополнительная кнопка выбора файла внутри пустого холста.
2. Раздел «Сетка»: заголовок слева, справа счётчик «36 ячеек», вычисляемый как колонки × ряды. Ниже подпись «Цвет линий». Под ней одна горизонтальная строка: цветовой образец, редактируемый HEX без отображаемого #, поле непрозрачности с суффиксом %, затем кнопка видимости. Ещё ниже два равных поля рядом: «Колонки» и «Ряды» с числом справа. У колонок, рядов и непрозрачности нет ползунков. Не сокращай подпись до «Непрозр.».
3. Раздел «Изображение»: заголовок и загрузка в одной строке; затем масштаб, яркость и контраст. Каждая строка имеет подпись, ползунок и число с суффиксом %. Размер подписей 10 px на компьютере, 11 px на телефоне. Единицы — отдельный текст рядом с input, а не часть вводимого значения.
4. Раздел «Эффект»: «Эффект» слева и поле с надписью Action справа в той же строке. Поле 154 × 32 px, фон #222424, радиус 8 px, текст 11 px Avito Sans Text Regular. Это подпись единственного эффекта; раскрывать несуществующее меню не нужно. Не помещай Action отдельным абзацем. На шаге 2 ниже только фиксированные значения; на шаге 3 регуляторы в порядке Свечение, Интенсивность, Шлейф, Чёткая зона. Суффиксы соответственно px, %, px, %.
5. Фон полей #212323, подписей #bcbcbc; ползунок 5 px толщиной: заполнение #8300e6, остаток #494c4c. Бегунок 18 × 12 px, овальный, полупрозрачный с бликом. Не используй круглые стандартные бегунки. Интервал между тремя колонками строки 10 px. На телефоне подпись 90 px, поле значения 58 px, оставшееся место — ползунок; длинная подпись не должна налезать на него.
6. «Скачать PNG» — капсула высотой 40 px, радиус 24 px, контурная иконка скачивания слева. Градиент сверху #9615ff вниз #6500bd, светлая тонкая обводка и внутренний блик. Кнопка находится в контейнере с фоном #292929 и отступом 6 px, радиусом 30 px; контейнер по центру рабочей области, снизу 24 px. На телефоне он в потоке, через 12 px после холста, шириной холста; кнопка 44 px высотой на всю ширину. Панель свойств начинается через 20 px после контейнера. Ссылка повторного сохранения не меняет размеры основной кнопки.
7. Холст: радиус 40 px на компьютере, на телефоне 6vw. При 1440 × 1000 его экранный прямоугольник x=262,y=202,w=600,h=600; при 1440 × 760 — x=262,y=72,w=600,h=600; при 390 × 844 — x=16,y=72,w=358,h=358. Это CSS-геометрия; внутренний canvas всегда 1080 × 1080. На низком экране сохраняй размер по ширине и разрешай вертикальную прокрутку, не перекрывая кнопкой изображение.
8. Все числовые настройки целочисленные с шагом 1. Дробное число округляй при завершении ввода, пустое поле возвращает последнее корректное значение. Единицы видимы и при редактировании. Отображаемый HEX без #; ввод с # разрешён.

ПРОВЕРКА ПЕРЕД СДАЧЕЙ КАЖДОГО ШАГА
Проверь структуру, а не только отсутствие ошибок: загрузка рядом с «Изображение»; у сетки нет ползунков; колонки и ряды рядом; счётчик ячеек есть; единицы видны; Action на одной строке с «Эффект»; скачивание в капсуле. Проверь контрольные прямоугольники и отсутствие наложения подписей на ползунки. Если пункт не выполнен, исправь собственный HTML до перехода к следующему шагу.
'''
(out/'specification.txt').write_text(s)
for i in range(1,4):
 f=out/f'prompt-{i}.txt';t=f.read_text().replace('Готовый HTML и его исходные стили использовать нельзя.','Нельзя использовать чужой готовый HTML или готовые стили редактора. Собственный HTML предыдущего шага использовать и дорабатывать можно.').replace('Контраст передавай в алгоритм ровно один раз, гамма 1.','Контраст применяется ровно один раз в каждой из двух независимых веток: подложке applyBase и эффекте preparePixels. Не применяй его к общему frame до разделения веток. Гамма 1.')
 t+='\nПеред сдачей выполни раздел «ПРОВЕРКА ПЕРЕД СДАЧЕЙ КАЖДОГО ШАГА» из specification.txt. Не добавляй ползунки к полям сетки. Сохрани единицы измерения, счётчик ячеек и указанные места кнопок.\n';f.write_text(t)
with ZipFile(p/'Participant-revised.zip','w',ZIP_DEFLATED) as z:
 for f in out.iterdir():z.write(f,f.name)
